-- Additive candidate over deployed731. Root assigns number; no full schema/data recreation.
BEGIN;SET ROLE hub2_authz_owner;
ALTER TABLE vault2.entries ADD manual jsonb;
CREATE TABLE vault2.legacy_registry(organization_id uuid NOT NULL,legacy_key_id text NOT NULL,entry_id uuid REFERENCES vault2.entries,legacy_subject text,principal_id uuid REFERENCES authz.principals,authority text NOT NULL DEFAULT'migration_pending'CHECK(authority IN('legacy','migration_pending','vault2','retired')),revision bigint NOT NULL DEFAULT 1,source_metadata jsonb NOT NULL DEFAULT'{}',cut_receipt jsonb,PRIMARY KEY(organization_id,legacy_key_id));
CREATE TABLE vault2.secret_operations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entry_id uuid NOT NULL REFERENCES vault2.entries,actor_id uuid NOT NULL,client_id uuid NOT NULL,idempotency_key text NOT NULL,fingerprint text NOT NULL,expected_revision bigint NOT NULL,target_ref text NOT NULL,state text NOT NULL DEFAULT'prepared'CHECK(state IN('prepared','intent','known','unknown','conflict')),provider_version bigint,receipt jsonb,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(actor_id,idempotency_key));
REVOKE ALL ON vault2.legacy_registry,vault2.secret_operations FROM PUBLIC,hub2_hufu,hub2_mem,hub2_v8,hub2_worker;
ALTER TABLE vault2.legacy_registry ENABLE ROW LEVEL SECURITY;ALTER TABLE vault2.secret_operations ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION vault2.registry(proof text,b jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,vault2 AS $$DECLARE i jsonb;e vault2.entries;pr v8.projects;old vault2.commands;result jsonb;created boolean:=false;owner_grant vault2.grants;owner_deadline timestamptz;creation_ceiling timestamptz;command_key text:=b->>'idempotency_key';fp text:=encode(public.digest(b::text,'sha256'),'hex');BEGIN
 IF b?'value'OR b?'secret_ref'OR b?'actor'OR b?'owner_id'THEN RAISE EXCEPTION 'invalid_registry_metadata';END IF;i:=vault2.identity(proof);IF coalesce(length(command_key),0)NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'invalid_input';END IF;
 IF b->>'entry_id'IS NOT NULL THEN SELECT * INTO e FROM vault2.entries WHERE id=(b->>'entry_id')::uuid FOR UPDATE;ELSE SELECT * INTO pr FROM v8.projects WHERE id=(b->>'project_id')::uuid;e.project_id:=pr.id;e.organization_id:=pr.organization_id;e.area_id:=(b->>'area_id')::uuid;e.owner_id:=(i->>'actor_id')::uuid;END IF;
 i:=authz.vault_current_identity(proof,e.project_id);IF NOT vault2.manager(i,e)THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended((i->>'actor_id')||':vaultregistry:'||command_key,0));SELECT * INTO old FROM vault2.commands WHERE actor_id=(i->>'actor_id')::uuid AND key=command_key;IF old.key IS NOT NULL THEN IF old.fingerprint IS DISTINCT FROM fp THEN RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE='23505';END IF;RETURN old.result;END IF;
 IF e.id IS NOT NULL AND EXISTS(SELECT FROM vault2.legacy_registry WHERE entry_id=e.id AND authority<>'vault2')THEN RAISE EXCEPTION 'vault_migration_authority_pending' USING ERRCODE='42501';END IF;IF e.area_id IS NOT NULL AND NOT EXISTS(SELECT FROM authz.resource_areas WHERE id=e.area_id AND project_id=e.project_id AND active)THEN RAISE EXCEPTION 'area_scope_mismatch' USING ERRCODE='42501';END IF;IF e.id IS NULL THEN
  IF(b->>'expected_revision')::bigint IS DISTINCT FROM 0 OR b->>'kind'NOT IN('model_api','service_login','generic','server_manage','dns_manage','cos_manage')THEN RAISE EXCEPTION 'invalid_input';END IF;
  created:=true;e.id:=gen_random_uuid();INSERT INTO vault2.entries(id,organization_id,project_id,area_id,name,label,description,kind,visibility,owner_id,secret_ref,execution_channel,manual)VALUES(e.id,e.organization_id,e.project_id,e.area_id,b->>'name',coalesce(b->>'label',b->>'name'),coalesce(b->>'description',''),b->>'kind',coalesce(b->>'visibility','organization'),e.owner_id,'bao:hub2/hufu/vault2/entries/'||e.id,coalesce(b->'execution_channel','{}'),b->'manual')RETURNING * INTO e;
 ELSE
  IF e.revision IS DISTINCT FROM(b->>'expected_revision')::bigint THEN RAISE EXCEPTION 'revision_conflict' USING ERRCODE='40001';END IF;
  -- Sensitivity/identity/ref cannot be downgraded or redirected by a metadata update.
  UPDATE vault2.entries SET label=coalesce(b->>'label',label),description=coalesce(b->>'description',description),visibility=coalesce(b->>'visibility',visibility),manual=CASE WHEN b?'manual'THEN b->'manual'ELSE manual END,active=coalesce((b->>'active')::boolean,active),revision=revision+1 WHERE id=e.id RETURNING * INTO e;
 END IF;
 i:=authz.vault_current_identity(proof,e.project_id);IF NOT vault2.manager(i,e)THEN RAISE EXCEPTION 'current_manager_required' USING ERRCODE='42501';END IF;
 -- Creating a normal owned resource includes its owner's initial use; it is not approving an application.
 IF created AND NOT vault2.high_sensitive(e)THEN
  creation_ceiling:=vault2.manager_deadline(i,e);IF creation_ceiling IS NULL OR creation_ceiling<=clock_timestamp()THEN RAISE EXCEPTION 'current_creation_authority_required' USING ERRCODE='42501';END IF;
  owner_deadline:=least(creation_ceiling,coalesce(e.provider_expires_at,'infinity'::timestamptz));
  IF owner_deadline IS NULL THEN RAISE EXCEPTION 'current_creation_authority_required' USING ERRCODE='42501';END IF;
  INSERT INTO vault2.grants(entry_id,principal_id,client_id,issued_by,until_revoked,expires_at,reason)
  VALUES(e.id,e.owner_id,(i->>'client_id')::uuid,(i->>'actor_id')::uuid,NOT isfinite(owner_deadline),CASE WHEN isfinite(owner_deadline)THEN owner_deadline ELSE NULL END,jsonb_build_object('basis','owned_resource_creation','application_self_approval',false))RETURNING * INTO owner_grant;
  INSERT INTO vault2.audit(actor_id,client_id,action,entry_id,grant_id,details)VALUES((i->>'actor_id')::uuid,(i->>'client_id')::uuid,'owner_initial_grant',e.id,owner_grant.id,jsonb_build_object('basis','owned_resource_creation','current_client_only',true,'until_revoked',owner_grant.until_revoked,'expires_at',owner_grant.expires_at));
 END IF;
 result:=jsonb_build_object('state',CASE WHEN e.active THEN'registered'ELSE'disabled'END,'entry_id',e.id,'name',e.name,'revision',e.revision,'secret_value_ready','not_inferred','owner_initial_grant_id',owner_grant.id,'owner_grant_scope',CASE WHEN owner_grant.id IS NOT NULL THEN'current_creator_client'ELSE NULL END,'owner_grant_expires_at',owner_grant.expires_at,'owner_grant_until_revoked',owner_grant.until_revoked);INSERT INTO vault2.audit(actor_id,client_id,action,entry_id,details)VALUES((i->>'actor_id')::uuid,(i->>'client_id')::uuid,'registry',e.id,result);INSERT INTO vault2.commands VALUES((i->>'actor_id')::uuid,command_key,fp,result);i:=authz.vault_current_identity(proof,e.project_id);IF NOT vault2.manager(i,e)THEN RAISE EXCEPTION 'current_manager_required' USING ERRCODE='42501';END IF;RETURN result;
END$$;
CREATE FUNCTION vault2.secret_prepare(proof text,b jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,vault2 AS $$DECLARE i jsonb;e vault2.entries;o vault2.secret_operations;fp text:=encode(public.digest(b::text,'sha256'),'hex');BEGIN
 i:=vault2.identity(proof);SELECT * INTO e FROM vault2.entries WHERE id=vault2.resolve_entry(i,b)FOR SHARE;i:=authz.vault_current_identity(proof,e.project_id);
 IF EXISTS(SELECT FROM vault2.legacy_registry WHERE entry_id=e.id AND authority<>'vault2')THEN RAISE EXCEPTION 'vault_migration_authority_pending' USING ERRCODE='42501';END IF;IF e.id IS NULL OR NOT e.active OR NOT vault2.manager(i,e)OR vault2.high_sensitive(e)THEN RAISE EXCEPTION 'ordinary_managed_entry_required' USING ERRCODE='42501';END IF;
 IF coalesce(length(b->>'idempotency_key'),0)NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'invalid_input';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended((i->>'actor_id')||':vaultrotate:'||(b->>'idempotency_key'),0));SELECT * INTO o FROM vault2.secret_operations WHERE actor_id=(i->>'actor_id')::uuid AND idempotency_key=b->>'idempotency_key';
 IF o.id IS NOT NULL THEN IF o.fingerprint IS DISTINCT FROM fp THEN RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE='23505';END IF;ELSE
  IF e.revision IS DISTINCT FROM(b->>'expected_revision')::bigint THEN RAISE EXCEPTION 'revision_conflict' USING ERRCODE='40001';END IF;
  INSERT INTO vault2.secret_operations(entry_id,actor_id,client_id,idempotency_key,fingerprint,expected_revision,target_ref)VALUES(e.id,(i->>'actor_id')::uuid,(i->>'client_id')::uuid,b->>'idempotency_key',fp,e.revision,'')RETURNING * INTO o;UPDATE vault2.secret_operations SET target_ref='bao:hub2/hufu/vault2/operations/'||o.id WHERE id=o.id RETURNING * INTO o;
 END IF;RETURN to_jsonb(o)-'fingerprint';
END$$;
CREATE FUNCTION vault2.secret_consume(proof text,b jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,vault2 AS $$DECLARE i jsonb;e vault2.entries;o vault2.secret_operations;BEGIN
 i:=vault2.identity(proof);SELECT * INTO o FROM vault2.secret_operations WHERE id=(b->>'operation_id')::uuid;SELECT * INTO e FROM vault2.entries WHERE id=o.entry_id FOR SHARE;i:=authz.vault_current_identity(proof,e.project_id);IF o.actor_id IS DISTINCT FROM(i->>'actor_id')::uuid OR NOT vault2.manager(i,e)OR NOT e.active OR vault2.high_sensitive(e)THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO o FROM vault2.secret_operations WHERE id=o.id FOR UPDATE;IF o.state='prepared'THEN IF e.revision<>o.expected_revision THEN RAISE EXCEPTION 'revision_conflict' USING ERRCODE='40001';END IF;UPDATE vault2.secret_operations SET state='intent'WHERE id=o.id RETURNING * INTO o;RETURN to_jsonb(o)||jsonb_build_object('send_authorized',true);END IF;RETURN to_jsonb(o)||jsonb_build_object('send_authorized',false);
END$$;
CREATE FUNCTION vault2.secret_finish(proof text,b jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,vault2 AS $$DECLARE i jsonb;e vault2.entries;o vault2.secret_operations;n bigint;result jsonb;BEGIN
 i:=vault2.identity(proof);SELECT * INTO o FROM vault2.secret_operations WHERE id=(b->>'operation_id')::uuid;SELECT * INTO e FROM vault2.entries WHERE id=o.entry_id FOR UPDATE;i:=authz.vault_current_identity(proof,e.project_id);
 IF o.actor_id IS DISTINCT FROM(i->>'actor_id')::uuid OR NOT vault2.manager(i,e)OR NOT e.active OR vault2.high_sensitive(e)THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';END IF;SELECT * INTO o FROM vault2.secret_operations WHERE id=o.id FOR UPDATE;
 IF o.state='known'THEN RETURN o.receipt;END IF;IF o.state NOT IN('intent','unknown')THEN RAISE EXCEPTION 'operation_state_conflict' USING ERRCODE='40001';END IF;
 IF b->>'outcome'='unknown'THEN UPDATE vault2.secret_operations SET state='unknown'WHERE id=o.id;RETURN jsonb_build_object('state','unknown','operation_id',o.id,'retained_state','query_same_operation_no_rewrite');END IF;
 n:=(b->>'provider_version')::bigint;IF b->>'outcome'IS DISTINCT FROM'known'OR n IS NULL OR n<1 THEN RAISE EXCEPTION 'invalid_input';END IF;
 i:=authz.vault_current_identity(proof,e.project_id);IF NOT vault2.manager(i,e)THEN RAISE EXCEPTION 'current_manager_required' USING ERRCODE='42501';END IF;IF e.revision<>o.expected_revision THEN UPDATE vault2.secret_operations SET state='conflict',provider_version=n WHERE id=o.id;RETURN jsonb_build_object('state','conflict','operation_id',o.id,'candidate_private_value_retained',true);END IF;
 UPDATE vault2.entries SET secret_ref=o.target_ref||'?version='||n,value_field='value',revision=revision+1 WHERE id=e.id RETURNING * INTO e;
 result:=jsonb_build_object('state','rotated','operation_id',o.id,'entry_id',e.id,'revision',e.revision,'provider_version',n,'upstream_old_credential_revoked',false);UPDATE vault2.secret_operations SET state='known',provider_version=n,receipt=result WHERE id=o.id;INSERT INTO vault2.audit(actor_id,client_id,action,entry_id,details)VALUES((i->>'actor_id')::uuid,(i->>'client_id')::uuid,'secret_rotated',e.id,result);RETURN result;
END$$;
CREATE FUNCTION vault2.secret_status(proof text,b jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,vault2 AS $$DECLARE i jsonb;e vault2.entries;o vault2.secret_operations;BEGIN i:=vault2.identity(proof);SELECT * INTO o FROM vault2.secret_operations WHERE id=(b->>'operation_id')::uuid;SELECT * INTO e FROM vault2.entries WHERE id=o.entry_id;IF o.id IS NULL OR NOT vault2.manager(i,e)THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';END IF;RETURN to_jsonb(o)-'fingerprint';END$$;
CREATE FUNCTION vault2.current_identity(proof text,b jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,vault2 AS $$DECLARE i jsonb;p authz.principals;BEGIN i:=vault2.identity(proof);SELECT * INTO p FROM authz.principals WHERE id=(i->>'actor_id')::uuid;RETURN jsonb_build_object('actor_id',p.id,'client_id',i->>'client_id','organization_id',p.organization_id,'kind',p.kind);END$$;
CREATE FUNCTION vault2.legacy_status(proof text,b jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,vault2 AS $$DECLARE i jsonb;r vault2.legacy_registry;e vault2.entries;BEGIN i:=vault2.identity(proof);SELECT * INTO r FROM vault2.legacy_registry WHERE organization_id=(i->>'organization_id')::uuid AND legacy_key_id=b->>'key';SELECT * INTO e FROM vault2.entries WHERE id=r.entry_id;IF r.legacy_key_id IS NULL THEN RETURN jsonb_build_object('state','unclassified','authority','migration_pending');END IF;IF e.id IS NOT NULL AND NOT vault2.visible(i,e)THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';END IF;RETURN jsonb_build_object('state','registry','key_id',r.legacy_key_id,'authority',r.authority,'entry_id',r.entry_id,'revision',r.revision,'identity_mapping',CASE WHEN r.principal_id IS NULL THEN'pending_mapping'ELSE'mapped'END);END$$;
CREATE FUNCTION vault2.manual_info(proof text,b jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,vault2 AS $$DECLARE i jsonb;e vault2.entries;BEGIN i:=vault2.identity(proof);SELECT * INTO e FROM vault2.entries WHERE id=vault2.resolve_entry(i,b);IF e.id IS NULL OR NOT vault2.visible(i,e)THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';END IF;RETURN jsonb_build_object('manual',e.manual);END$$;
REVOKE ALL ON FUNCTION vault2.manual_info(text,jsonb)FROM PUBLIC,hub2_hufu,hub2_mem,hub2_v8,hub2_worker;GRANT EXECUTE ON FUNCTION vault2.manual_info(text,jsonb)TO hub2_hufu;
-- Root-only service identity provisioning. Lookup is a server/Hufu capability, not a public caller actor selector.
CREATE TABLE vault2.service_bindings(legacy_subject text PRIMARY KEY,principal_id uuid NOT NULL REFERENCES authz.principals,profile_ref text NOT NULL CHECK(profile_ref LIKE'bao:hub2/hufu/vault2/serviceprofiles/%'),active boolean NOT NULL DEFAULT true,registered_by text NOT NULL,source_proof jsonb NOT NULL);
REVOKE ALL ON vault2.service_bindings FROM PUBLIC,hub2_hufu,hub2_mem,hub2_v8,hub2_worker;ALTER TABLE vault2.service_bindings ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION vault2.lookup_service(subject text)RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,vault2 AS $$SELECT jsonb_build_object('principal_id',p.id,'profile_ref',s.profile_ref)FROM vault2.service_bindings s JOIN authz.principals p ON p.id=s.principal_id WHERE s.legacy_subject=subject AND s.active AND p.active AND p.kind='service'$$;
REVOKE ALL ON FUNCTION vault2.current_identity(text,jsonb),vault2.legacy_status(text,jsonb),vault2.lookup_service(text)FROM PUBLIC,hub2_hufu,hub2_mem,hub2_v8,hub2_worker;
GRANT EXECUTE ON FUNCTION vault2.current_identity(text,jsonb),vault2.legacy_status(text,jsonb),vault2.lookup_service(text)TO hub2_hufu;
ALTER FUNCTION vault2.reveal_prepare(text,jsonb)RENAME TO reveal_prepare_pre_registry_next;
REVOKE ALL ON FUNCTION vault2.reveal_prepare_pre_registry_next(text,jsonb)FROM PUBLIC,hub2_hufu,hub2_mem,hub2_v8,hub2_worker;
CREATE FUNCTION vault2.reveal_prepare(proof text,b jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,vault2 AS $$DECLARE i jsonb;e vault2.entries;r jsonb;BEGIN i:=vault2.identity(proof);SELECT * INTO e FROM vault2.entries WHERE id=vault2.resolve_entry(i,b);IF EXISTS(SELECT FROM vault2.legacy_registry WHERE entry_id=e.id AND authority<>'vault2')THEN RAISE EXCEPTION 'vault_migration_authority_pending' USING ERRCODE='42501';END IF;r:=vault2.reveal_prepare_pre_registry_next(proof,b);RETURN r||jsonb_build_object('manual',e.manual);END$$;
REVOKE ALL ON FUNCTION vault2.reveal_prepare(text,jsonb)FROM PUBLIC,hub2_hufu,hub2_mem,hub2_v8,hub2_worker;GRANT EXECUTE ON FUNCTION vault2.reveal_prepare(text,jsonb)TO hub2_hufu;
-- Exact old rule: manager authority does not authorize self-approval.
ALTER FUNCTION vault2.decide(text,jsonb)RENAME TO decide_pre_registry_next;
REVOKE ALL ON FUNCTION vault2.decide_pre_registry_next(text,jsonb)FROM PUBLIC,hub2_hufu,hub2_mem,hub2_v8,hub2_worker;
CREATE FUNCTION vault2.decide(proof text,b jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,vault2 AS $$DECLARE i jsonb;a vault2.applications;BEGIN i:=vault2.identity(proof);SELECT * INTO a FROM vault2.applications WHERE id=(b->>'application_id')::uuid;IF b->>'decision'='approve'AND a.applicant_id=(i->>'actor_id')::uuid THEN RAISE EXCEPTION 'self_approval_forbidden' USING ERRCODE='42501';END IF;RETURN vault2.decide_pre_registry_next(proof,b);END$$;
REVOKE ALL ON FUNCTION vault2.registry(text,jsonb),vault2.secret_prepare(text,jsonb),vault2.secret_consume(text,jsonb),vault2.secret_finish(text,jsonb),vault2.secret_status(text,jsonb),vault2.decide(text,jsonb)FROM PUBLIC,hub2_hufu,hub2_mem,hub2_v8,hub2_worker;
GRANT EXECUTE ON FUNCTION vault2.registry(text,jsonb),vault2.secret_prepare(text,jsonb),vault2.secret_consume(text,jsonb),vault2.secret_finish(text,jsonb),vault2.secret_status(text,jsonb),vault2.decide(text,jsonb)TO hub2_hufu;
RESET ROLE;COMMIT;
